INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0001-2026-09-06', 'Putin Holds "Substantive" Talks With U.S. Envoys as Ukraine Signals Willingness to Pause Strikes on Moscow', 'putin-talks-us-envoys-ukraine-pause-strikes', 'President Zelensky announces readiness to halt airstrikes through Monday following back-channel dialogue with American intermediaries.', 'Russian and American officials engaged in what the Kremlin described as frank and substantive discussions, while Ukraine signalled a temporary halt to strikes on the Russian capital.', '<p class="lead">Russian President Vladimir Putin hosted U.S. envoys Steve Witkoff and Jared Kushner in Moscow on Friday for what the Kremlin described as "substantive and frank" discussions about the war in Ukraine — the most senior-level diplomatic engagement between Washington and Moscow in months.</p>
      <p>The talks, held inside the Kremlin''s ornate Ekaterina Hall, lasted approximately three hours and covered a range of issues including potential ceasefire frameworks, humanitarian corridors, and energy security arrangements in the Black Sea region.</p>
      <p>Separately, Ukrainian President Volodymyr Zelensky announced late Friday that Ukraine is prepared to refrain from airstrikes against Moscow through Monday, contingent on reciprocal restraint from Russian forces along the southern front.</p>
      <blockquote>"We are not offering surrender — we are offering silence. If silence can buy even forty-eight hours of breathing room for diplomacy, then every hour of restraint is worth the risk." — President Volodymyr Zelensky</blockquote>
      <p>Despite cautious optimism among Western diplomats, senior officials in Washington stressed that no formal breakthrough had been achieved and that significant gaps remain between Russian and Ukrainian negotiating positions on territorial sovereignty and security guarantees.</p>
      <p>Financial markets responded with measured optimism: European natural gas futures fell 4.2 percent, and the Ukrainian hryvnia strengthened against the dollar for the first time in six weeks.</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1548345680-f5475ea5df84?w=1200&h=750&fit=crop', 'The Kremlin complex seen from across the Moscow River during the high-level diplomatic session | Photo: Reuters / Moscow Bureau', NULL, 1, 1, 'published', 1, '["Russia","Ukraine","Diplomacy","United States"]', 'english', '2026-09-07T04:12:18.414Z', '2026-09-07T05:12:18.414Z', '2026-09-07T05:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0002-2026-09-06', 'Mount Anak Krakatau Erupts, Forcing Closure of Jakarta''s Main Airport and Disrupting Dozens of Flights', 'mount-anak-krakatau-erupts-jakarta-airport-closed', 'Indonesia raises volcanic alert to highest level as ash clouds force Soekarno-Hatta International Airport to divert all commercial traffic.', 'A powerful eruption of Mount Anak Krakatau has shut down Jakarta''s primary international airport, stranding thousands of passengers and disrupting regional air travel across Southeast Asia.', '<p class="lead">Mount Anak Krakatau, the volcanic island born from the catastrophic 1883 eruption of Krakatoa in Indonesia''s Sunda Strait, erupted violently early Saturday morning, sending a towering column of ash and pyroclastic material more than 15 kilometres into the atmosphere.</p>
      <p>Soekarno-Hatta International Airport, Jakarta''s main aviation hub serving over 60 million passengers annually, was forced to halt all departures and arrivals as volcanic ash contaminated airspace across western Java and southern Sumatra.</p>
      <p>Indonesia''s Centre for Volcanology and Geological Hazard Mitigation elevated the alert level for the volcano to Level IV — the highest tier — and urged residents in coastal areas of Banten and Lampung provinces to remain at least five kilometres from the shoreline due to the risk of volcanic tsunamis.</p>
      <p>Garuda Indonesia, Lion Air, and several regional carriers cancelled a combined total of 87 scheduled flights. Airlines across Southeast Asia are rerouting long-haul services to avoid the ash cloud, which is drifting northwest toward the Indian Ocean.</p>
      <p>"We are deploying additional monitoring buoys in the Sunda Strait and coordinating with the Pacific Tsunami Warning Center to ensure rapid early warning capability," said Dr. Hendra Gunawan, head of the national geological agency.</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1462332420958-a05d1e002413?w=1200&h=750&fit=crop', 'Volcanic eruption sends ash plume into the atmosphere above the Sunda Strait, viewed from Anyer, Banten Province | Photo: BNPB Indonesia', NULL, 1, 0, 'published', NULL, '["Indonesia","Volcano","Natural Disaster","Aviation"]', 'english', '2026-09-07T02:12:18.414Z', '2026-09-07T04:12:18.414Z', '2026-09-07T04:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0003-2026-09-06', 'U.S. Navy Destroys Three Iranian Oil Tankers in Escalating Gulf Confrontation', 'us-navy-destroys-iranian-oil-tankers-gulf', 'Pentagon confirms strikes on vessels accused of funding sanctioned military operations; Tehran vows "tougher reprisals."', 'The U.S. military confirmed the destruction of three Iranian oil tankers in the Persian Gulf, marking a significant escalation in the ongoing conflict between Washington and Tehran.', '<p class="lead">The United States military confirmed on Friday the destruction of three Iranian oil tankers operating in the Persian Gulf, in what the Pentagon described as a response to attempted missile attacks on American naval vessels earlier in the week.</p>
      <p>The strikes, carried out by guided-missile destroyers of the U.S. Fifth Fleet, targeted tankers that American intelligence officials said were part of a sanctions-evasion network used to fund Iran''s Islamic Revolutionary Guard Corps and its regional proxy operations.</p>
      <p>Iran''s Supreme National Security Council condemned the strikes as "acts of maritime piracy" and warned of "tougher reprisals," escalating rhetoric that has alarmed energy markets and prompted emergency consultations at NATO headquarters in Brussels.</p>
      <p>Brent crude futures surged 6.8 percent to $94.70 per barrel in Asian trading following the announcement, while Lloyd''s of London raised its war-risk insurance premiums for vessels transiting the Strait of Hormuz by an additional 1.5 percentage points.</p>
      <p>The United Nations Security Council has called an emergency session for Monday to address the escalation, with European members pushing for a maritime de-escalation framework modeled on Cold War-era naval incidents agreements.</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1580309237429-661ea0e18e62?w=1200&h=750&fit=crop', 'U.S. Navy destroyer on patrol in the Persian Gulf during heightened security operations | Photo: U.S. Navy / Released', NULL, 0, 0, 'published', 3, '["Iran","United States","Military","Oil"]', 'english', '2026-09-07T00:12:18.414Z', '2026-09-07T03:12:18.414Z', '2026-09-07T03:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0004-2026-09-06', 'South Korea Hits Record $709 Billion in Cumulative Exports, Surpassing Annual Best', 'south-korea-record-exports-709-billion', 'Semiconductor and electric vehicle battery shipments drive the Republic of Korea past its previous full-year export record with four months still remaining.', 'South Korea achieved a historic milestone as cumulative exports for 2026 reached $709.4 billion, surpassing the previous annual record with the year barely three-quarters complete.', '<p class="lead">The Republic of Korea has shattered its own trade records, with cumulative merchandise exports reaching $709.4 billion as of September 5, 2026 — surpassing the previous full-year record set in 2022 with nearly four months of the fiscal year still remaining.</p>
      <p>The Korea Customs Service attributed the landmark achievement primarily to surging global demand for advanced semiconductors, high-capacity EV battery cells, and next-generation display panels, which together account for roughly 42 percent of the nation''s total export revenue.</p>
      <p>Samsung Electronics and SK Hynix have been key contributors, with combined memory chip exports alone exceeding $148 billion year-to-date. Meanwhile, battery giants LG Energy Solution and Samsung SDI have expanded production to meet orders from European and North American automakers transitioning to electric platforms.</p>
      <p>"This milestone demonstrates that Korea''s strategic investments in semiconductor manufacturing, battery technology, and advanced materials science are paying dividends at scale," said Trade Minister Ahn Duk-geun at a press briefing in Seoul.</p>
      <p>The Korean won strengthened 0.6 percent against the dollar following the announcement, and the benchmark KOSPI index rose 1.2 percent in morning trading.</p>', 'Dhananjay Singh', 'Economy', 'https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?w=1200&h=750&fit=crop', 'Container vessels at Busan Port, South Korea''s largest maritime trade hub handling over 22 million TEUs annually | Photo: Korea Maritime Institute', NULL, 0, 0, 'published', 4, '["South Korea","Economy","Trade","Semiconductors"]', 'english', '2026-09-07T01:12:18.414Z', '2026-09-07T03:12:18.414Z', '2026-09-07T03:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0005-2026-09-06', 'Building Collapse in New Delhi Kills One, Dozens Feared Trapped Under Rubble', 'building-collapse-new-delhi-dozens-trapped', 'Rescue workers deploy heavy cranes and canine units as a four-storey residential structure collapses in the Bhajanpura locality of northeast Delhi.', 'A four-storey residential building in New Delhi collapsed on Sunday morning, killing at least one person and leaving dozens of residents feared trapped beneath the debris.', '<p class="lead">A four-storey residential building in the densely populated Bhajanpura neighbourhood of northeast New Delhi collapsed early Sunday morning, killing at least one person and leaving an estimated 30 to 40 residents trapped beneath tonnes of concrete and steel debris.</p>
      <p>The National Disaster Response Force deployed four specialised urban search-and-rescue teams to the site within 45 minutes of the collapse, along with heavy hydraulic cranes, acoustic life detectors, and canine units trained to locate survivors beneath rubble.</p>
      <p>By midday, rescue teams had extracted 12 survivors, including three children, from the wreckage. At least eight of the rescued were transported to Lok Nayak Hospital with serious crush injuries. Emergency medical tents were erected at the perimeter as ambulance teams from five hospitals coordinated triage operations.</p>
      <p>Delhi Chief Minister Rekha Gupta visited the site and announced immediate ex-gratia compensation of ₹10 lakh for the family of the deceased and ₹2 lakh for each seriously injured survivor.</p>
      <p>Municipal records indicate that the building, constructed in 2003, had been flagged for structural deficiencies during a routine inspection in January 2025, but no evacuation or remediation orders were issued. The Delhi Development Authority has launched an investigation into the regulatory failure.</p>', 'Dhananjay Singh', 'India', 'https://images.unsplash.com/photo-1567521464027-f127ff144326?w=1200&h=750&fit=crop', 'Emergency rescue operations at the collapse site in Bhajanpura, northeast Delhi | Photo: PTI / Delhi Fire Service', NULL, 0, 0, 'published', 5, '["India","Delhi","Disaster","Rescue"]', 'english', '2026-09-07T03:12:18.414Z', '2026-09-07T05:12:18.414Z', '2026-09-07T05:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0006-2026-09-06', 'Wildfires Rage Across the United States With Over 118 New Blazes Reported Nationwide', 'us-wildfires-118-new-fires-nationwide', 'More than 16,500 firefighting personnel deployed as drought conditions and record heat fuel blazes from California to the Appalachian foothills.', 'The United States is battling a devastating wildfire season with over 118 new fires reported across the country and more than 16,500 personnel committed to containment efforts.', '<p class="lead">The National Interagency Fire Center reported on Saturday that over 118 new wildfires have been documented across the United States in the past 72 hours, with more than 16,500 federal, state, and local firefighting personnel deployed to active containment operations in 14 states.</p>
      <p>California continues to bear the brunt of the fire season, with the Mendocino Complex blaze alone consuming over 42,000 acres of chaparral and timber. Governor Gavin Newsom declared a state of emergency for Mendocino and Lake counties and requested federal disaster assistance from the White House.</p>
      <p>In Oregon, the Bootleg Creek Fire has forced the evacuation of three rural communities and is threatening critical electrical transmission infrastructure that serves the Portland metropolitan area. PacifiCorp has preemptively de-energised segments of its high-voltage grid to reduce ignition risk.</p>
      <p>"We are operating in unprecedented conditions. Fuel moisture levels in many Western forests are at record lows for this time of year, and wind patterns are creating fire behaviour we haven''t seen before," said NIFC Incident Commander Sarah Chen.</p>
      <p>The Biden administration announced the deployment of ten additional C-130 air tanker sorties and activated mutual aid agreements with Canadian and Australian firefighting agencies.</p>', 'Dhananjay Singh', 'Environment', 'https://images.unsplash.com/photo-1473448912268-2022ce9509d8?w=1200&h=750&fit=crop', 'Firefighters battle a wall of flame advancing through drought-parched forest in Northern California | Photo: CAL FIRE / Official Release', NULL, 0, 0, 'published', 6, '["Wildfire","Climate","United States","Emergency"]', 'english', '2026-09-07T02:12:18.414Z', '2026-09-07T04:12:18.414Z', '2026-09-07T04:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0007-2026-09-06', 'WHO Launches Global Mpox Vaccine Stockpile Initiative for Equitable Access', 'who-launches-global-mpox-vaccine-stockpile', 'International health agency coordinates with pharmaceutical partners to ensure rapid vaccine deployment during outbreaks in under-resourced regions.', 'The World Health Organisation has launched a new global initiative to establish an emergency stockpile of mpox vaccines, aiming to eliminate disparities in outbreak response capacity between wealthy and developing nations.', '<p class="lead">The World Health Organisation announced on Friday the establishment of a global mpox vaccine stockpile, coordinated with international pharmaceutical partners and funded through a consortium of sovereign donors and multilateral development banks.</p>
      <p>The initiative aims to pre-position approximately 5 million doses of third-generation smallpox-derived vaccines at regional distribution hubs across sub-Saharan Africa, Southeast Asia, and Latin America — the regions most vulnerable to future mpox outbreaks.</p>
      <p>WHO Director-General Dr. Tedros Adhanom Ghebreyesus said the programme was designed to address the "vaccination equity gap" that was starkly exposed during the 2022-2024 mpox pandemic, when wealthy nations secured the vast majority of available doses while African countries with the highest caseloads waited months for deliveries.</p>
      <p>Bavarian Nordic, the Danish manufacturer of the Jynneos vaccine, has committed to producing 3 million doses at discounted pricing for the stockpile, with additional contributions expected from Japanese manufacturer KM Biologics.</p>
      <p>The Global Fund, GAVI, and the World Bank''s Pandemic Fund have collectively pledged $280 million over three years to finance procurement, cold-chain infrastructure, and training for frontline health workers in recipient countries.</p>', 'Dhananjay Singh', 'Health', 'https://images.unsplash.com/photo-1584036561566-baf8f5f1b144?w=1200&h=750&fit=crop', 'Medical workers prepare vaccine doses at a WHO-coordinated distribution centre | Photo: WHO / Regional Africa Office', NULL, 0, 0, 'published', 7, '["WHO","Health","Vaccines","Mpox"]', 'english', '2026-09-06T22:12:18.414Z', '2026-09-07T02:12:18.414Z', '2026-09-07T02:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0008-2026-09-06', 'Global Trade Hits New Highs but Least-Developed Countries Fall Further Behind in Digital Exports', 'global-trade-highs-ldc-digital-gap-widens', 'UNCTAD report finds services are reshaping world trade flows, but AI readiness and digital infrastructure remain starkly unequal.', 'A new UNCTAD report reveals that while global trade in services is reaching record levels, the world''s poorest nations are being left further behind in digital commerce and artificial intelligence preparedness.', '<p class="lead">The United Nations Conference on Trade and Development published its annual Global Trade Update on Friday, revealing that while international trade in services has reached record volumes, the gap between advanced economies and least-developed countries in digital exports and artificial intelligence readiness is widening at an alarming pace.</p>
      <p>Total global merchandise and services trade is on track to exceed $33 trillion in 2026, driven primarily by digitally-delivered services, cloud computing infrastructure, and cross-border data flows. However, the report found that the 46 nations classified as least-developed countries collectively account for less than 0.4 percent of global digitally-delivered services exports.</p>
      <p>"The digital divide is no longer just about internet access — it is about AI readiness, data governance capacity, and the ability to participate in increasingly automated global value chains," said UNCTAD Secretary-General Rebeca Grynspan.</p>
      <p>The report recommends targeted investments in digital infrastructure, regulatory harmonisation, and technology transfer mechanisms to prevent the emergence of a permanent "two-tier" global trading system.</p>', 'Dhananjay Singh', 'Economy', 'https://images.unsplash.com/photo-1504711434969-e33886168d8c?w=1200&h=750&fit=crop', 'Shipping containers at a major port terminal reflecting the scale of modern global trade | Photo: UNCTAD / Trade Statistics Division', NULL, 0, 0, 'published', 8, '["Trade","Economy","UNCTAD","Digital Divide"]', 'english', '2026-09-06T20:12:18.414Z', '2026-09-07T01:12:18.414Z', '2026-09-07T01:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0009-2026-09-06', 'Iran Threatens "Tougher Reprisals" After Claiming Strikes on U.S.-Linked Bases in Kuwait and UAE', 'iran-threatens-reprisals-claims-strikes-kuwait-uae', 'Tehran says missiles and drones struck American military facilities in the Gulf; Pentagon denies operational damage to any U.S. installation.', 'Iran has threatened tougher reprisals and claimed to have struck U.S.-associated military facilities in Kuwait and the UAE, further escalating tensions in the Persian Gulf region.', '<p class="lead">Iran''s Islamic Revolutionary Guard Corps has claimed responsibility for missile and drone strikes on military installations associated with American forces in Kuwait and the United Arab Emirates, marking a dramatic escalation in the Gulf confrontation that has rattled global energy markets and strained regional alliances.</p>
      <p>The Pentagon issued a statement denying any "operational damage to U.S. military installations" and said that American air defence systems intercepted the majority of incoming projectiles. However, Kuwaiti authorities confirmed minor structural damage at Ali Al Salem Air Base and ordered a temporary suspension of civilian flight operations from Kuwait International Airport as a precautionary measure.</p>
      <p>Iran''s Supreme Leader Ayatollah Ali Khamenei, in a nationally televised address, warned that Tehran possesses "strategic patience but also strategic capability" and that any further strikes on Iranian assets would be met with "responses that America''s regional architecture cannot absorb."</p>
      <p>The European Union''s foreign policy chief called an emergency ministerial meeting for Tuesday to discuss a coordinated diplomatic response, while China''s Ministry of Foreign Affairs urged "maximum restraint from all parties" and offered to host mediation talks in Beijing.</p>
      <p>Global oil prices spiked above $95 per barrel in overnight trading, while safe-haven assets including gold and the Swiss franc saw sharp inflows.</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1597200381847-30ec200eeb9a?w=1200&h=750&fit=crop', 'Military radar installation monitoring airspace over the Persian Gulf region | Photo: AFP / Gulf Security Bureau', NULL, 0, 0, 'published', 9, '["Iran","Middle East","Military","Gulf"]', 'english', '2026-09-06T23:12:18.414Z', '2026-09-07T03:12:18.414Z', '2026-09-07T03:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0010-2026-09-06', 'Serbia''s Ruling Party Nominates President Vučić as Lead Candidate for Snap Parliamentary Election', 'serbia-vucic-nominated-parliamentary-election', 'The Serbian Progressive Party backs Aleksandar Vučić to lead its ticket in an election widely seen as a referendum on his decade of political dominance.', 'The Serbian Progressive Party has formally nominated President Aleksandar Vučić as its lead candidate for the upcoming snap parliamentary election, consolidating his grip on the country''s political landscape.', '<p class="lead">The ruling Serbian Progressive Party officially nominated President Aleksandar Vučić as its lead candidate for snap parliamentary elections expected to take place in late October, a move that cements his position as the dominant force in Serbian politics for over a decade.</p>
      <p>The nomination was approved by acclamation at a party congress in Belgrade''s Sava Center attended by over 15,000 delegates, with Vučić delivering a two-hour keynote address that combined economic optimism with sharp criticism of the European Union''s enlargement timetable for the Western Balkans.</p>
      <p>Opposition parties, which have struggled to present a unified front against Vučić''s political machine, accused the president of calling snap elections specifically to capitalise on a temporary uptick in approval ratings following recent infrastructure investments and a favourable IMF review of Serbia''s fiscal position.</p>
      <p>"This is not a democratic exercise — it is a coronation," said opposition leader Marinika Tepić. "The president controls the media landscape, the electoral commission, and most municipal governments. These are elections in form but not in substance."</p>
      <p>The European Parliament''s rapporteur for Serbia urged free and fair electoral conditions and warned that further democratic backsliding could jeopardise Serbia''s EU accession timeline.</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1529107386315-e1a2ed48a620?w=1200&h=750&fit=crop', 'Belgrade''s National Assembly building, seat of the Serbian Parliament | Photo: AP / Belgrade Correspondent', NULL, 0, 0, 'published', 10, '["Serbia","Elections","Europe","Politics"]', 'english', '2026-09-06T21:12:18.414Z', '2026-09-07T01:12:18.414Z', '2026-09-07T01:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0011-2026-09-06', 'Gaza Ceasefire Violations Continue as Localised Efforts Underway to Restore Power Infrastructure', 'gaza-ceasefire-violations-power-restoration', 'Three Palestinians injured by Israeli army fire amid fragile truce; engineers work to repair critical electrical grid connections.', 'Tensions in Gaza persist with ongoing ceasefire violations and three Palestinians injured by Israeli military fire, even as local engineers race to repair damaged electrical infrastructure.', '<p class="lead">The fragile ceasefire in Gaza continued to fray on Saturday as the Palestinian Health Ministry reported that three civilians were injured by Israeli army fire in the northern part of the territory, while international observers documented at least seven separate incidents of gunfire along the buffer zone.</p>
      <p>Despite the escalatory incidents, localised efforts to restore critical infrastructure showed signs of cautious progress. A team of Palestinian electrical engineers, working under coordination with UNRWA and the International Committee of the Red Cross, successfully reconnected a 22-kilovolt feeder line serving the Jabalia refugee camp — restoring intermittent power to approximately 35,000 residents for the first time in four months.</p>
      <p>UNICEF reported that the restoration of even limited electrical capacity has allowed the reopening of two water desalination plants, which are critical to preventing the spread of waterborne diseases in the overcrowded enclave.</p>
      <p>The UN Special Coordinator for the Middle East Peace Process urged both sides to recommit to the ceasefire framework and warned that continued violations risk a full resumption of hostilities that would push humanitarian conditions "past the point of recovery."</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1542224566-6e85f2e6772f?w=1200&h=750&fit=crop', 'Humanitarian aid workers coordinate relief operations in a conflict zone | Photo: ICRC / Field Documentation Unit', NULL, 0, 0, 'published', 11, '["Gaza","Palestine","Ceasefire","Humanitarian"]', 'english', '2026-09-07T01:12:18.414Z', '2026-09-07T04:12:18.414Z', '2026-09-07T04:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0012-2026-09-06', 'EU Lawmakers Finalise AI Act Enforcement Mechanism After Two Years of Debate', 'eu-ai-act-enforcement-mechanism-finalised', 'Member states align on audit procedures, compliance timelines, and penalty structures for the world''s most comprehensive artificial intelligence regulation.', 'Two years after the EU''s landmark Artificial Intelligence Act took effect, European lawmakers have finally agreed on the enforcement mechanism that will govern audits, compliance deadlines, and fines.', '<p class="lead">European Union legislators have completed a two-year negotiation to finalise the enforcement mechanism for the Artificial Intelligence Act — the world''s most comprehensive regulatory framework for AI systems — clearing the final bureaucratic hurdle for full implementation across all 27 member states.</p>
      <p>The agreed mechanism establishes a tiered audit system where AI systems classified as "high risk" — including those used in hiring, criminal justice, immigration processing, and critical infrastructure — must undergo independent conformity assessments every 18 months by accredited evaluation bodies.</p>
      <p>Companies found in violation of the Act''s provisions face fines of up to 7 percent of global annual turnover or €35 million, whichever is greater. For prohibited AI practices, including real-time mass biometric surveillance and social scoring systems, penalties rise to 10 percent of global revenue.</p>
      <p>The regulation is expected to have significant extraterritorial impact, as any company offering AI services to European consumers — regardless of where it is headquartered — must comply with the Act''s transparency, safety, and human oversight requirements.</p>
      <p>Tech industry groups have expressed concern about the compliance burden on smaller AI startups, while digital rights organisations have broadly welcomed the framework as a "global benchmark for accountable AI governance."</p>', 'Dhananjay Singh', 'Technology', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1200&h=750&fit=crop', 'Artificial intelligence circuit visualization representing the regulatory frontier of AI governance | Photo: European Commission / Digital Policy Unit', NULL, 0, 0, 'published', 12, '["AI","EU","Regulation","Technology"]', 'english', '2026-09-06T18:12:18.414Z', '2026-09-07T00:12:18.414Z', '2026-09-07T00:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0013-2026-09-06', 'Lebanon Military Operations Continue to Pose Civilian Risk Amid Fragile Political Transition', 'lebanon-military-operations-civilian-risk', 'UN peacekeepers document rising incidents along the Blue Line as parliamentary coalition negotiations stall in Beirut.', 'Military activity in southern Lebanon continues to endanger civilians as the country navigates a fragile political transition and stalled coalition talks.', '<p class="lead">United Nations peacekeeping forces in Lebanon have documented a sustained increase in military activity along the Blue Line — the demarcation line separating Lebanon from Israel — with at least 14 incidents of exchanges of fire recorded over the past week, according to a confidential UNIFIL situation report obtained by The Meridiān.</p>
      <p>The report notes that three civilian homes in the village of Kfar Kila sustained damage from indirect fire, and that a UNIFIL patrol vehicle was struck by shrapnel, though no peacekeeping personnel were injured.</p>
      <p>In Beirut, efforts to form a new coalition government have stalled, with the three main parliamentary blocs unable to agree on the distribution of key cabinet portfolios, particularly the ministries of defence and finance.</p>
      <p>The humanitarian situation in southern Lebanon remains precarious, with the UN Office for the Coordination of Humanitarian Affairs estimating that approximately 120,000 residents have been displaced from border communities since tensions escalated in late 2025.</p>
      <p>France''s special envoy for Lebanon is expected to arrive in Beirut on Wednesday to facilitate discussions between political factions and to push for a rapid formation of government as a precondition for unlocking international reconstruction aid.</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1569077382689-5ebf9e367b78?w=1200&h=750&fit=crop', 'View of the historic cityscape with Mediterranean coastline reflecting Lebanon''s complex geopolitical position | Photo: UN / UNIFIL Documentation', NULL, 0, 0, 'published', 13, '["Lebanon","UNIFIL","Middle East","Conflict"]', 'english', '2026-09-06T19:12:18.414Z', '2026-09-07T01:12:18.414Z', '2026-09-07T01:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0014-2026-09-06', 'Brent Crude Surges Past $95 as Gulf Tensions and Supply Disruptions Rattle Energy Markets', 'brent-crude-surges-95-gulf-tensions', 'Oil benchmarks hit 18-month highs as tanker strikes, Persian Gulf confrontation, and OPEC+ production discipline tighten the global supply outlook.', 'Brent crude oil prices surged past $95 per barrel for the first time in 18 months as escalating military confrontation in the Persian Gulf combined with disciplined OPEC+ output cuts to tighten global energy supply.', '<p class="lead">Brent crude oil futures breached $95 per barrel in Asian trading on Saturday morning, reaching their highest level since March 2025, as a confluence of geopolitical tensions in the Persian Gulf, targeted disruptions to Iranian oil exports, and continued OPEC+ production discipline created what energy analysts are calling the "tightest supply outlook in two years."</p>
      <p>The immediate catalyst was the U.S. Navy''s destruction of three Iranian oil tankers, which removed an estimated 2.1 million barrels of crude from transit. But analysts at Goldman Sachs noted that the price surge reflects deeper structural factors, including declining commercial crude inventories in OECD nations, which have fallen to their lowest seasonal levels since 2014.</p>
      <p>West Texas Intermediate crude, the U.S. benchmark, rose in tandem to $91.40 per barrel. U.S. gasoline futures for October delivery jumped 4.3 percent, suggesting that consumers may see price increases at the pump within days.</p>
      <p>OPEC+ members are scheduled to meet on September 15 to review production targets, and several delegates indicated that the alliance is unlikely to increase output despite the price surge, citing the need to "maintain market stability and producer revenue predictability."</p>', 'Dhananjay Singh', 'Economy', 'https://images.unsplash.com/photo-1611273426858-450d8e3c9fce?w=1200&h=750&fit=crop', 'Oil refinery complex operations illuminated at dusk, reflecting the critical role of petroleum infrastructure in global energy supply | Photo: Reuters / Energy Markets', NULL, 0, 0, 'published', 14, '["Oil","Energy","Markets","OPEC"]', 'english', '2026-09-07T00:12:18.414Z', '2026-09-07T03:12:18.414Z', '2026-09-07T03:12:18.414Z');
INSERT INTO articles (id, title, slug, subtitle, excerpt, content, author, category, image_url, image_caption, video_url, featured, is_breaking, status, homepage_position, tags, language, created_at, updated_at, published_at) VALUES ('n-0015-2026-09-06', 'Brussels Greenlights Fifteenth Sanctions Package Targeting Russian Sanctions-Evasion Networks', 'eu-fifteenth-sanctions-package-russia', 'The European Council approves new measures targeting third-country intermediaries, energy export ceilings, and shadow fleet tankers facilitating Russian oil shipments.', 'The European Union approved its fifteenth package of sanctions against Russia, targeting a sophisticated network of third-country intermediaries and shadow fleet tankers used to circumvent existing trade restrictions.', '<p class="lead">The European Council formally approved the fifteenth package of economic sanctions against Russia on Friday, expanding the bloc''s most extensive sanctions regime to target a sprawling network of third-country companies and individuals accused of helping Moscow evade existing trade restrictions and finance its war effort in Ukraine.</p>
      <p>The package names 78 new entities and 42 individuals across Turkey, the United Arab Emirates, Kazakhstan, and Georgia that EU investigators identified as key nodes in sanctions-circumvention supply chains for dual-use technology, including semiconductor components, precision machine tools, and navigation equipment.</p>
      <p>New measures also tighten energy export ceilings by lowering the price cap on Russian seaborne crude from $60 to $45 per barrel and introducing a mandatory hull-tracking registry for all tankers calling at EU ports to combat the growing Russian "shadow fleet" — an estimated 600 aging vessels operating without Western insurance coverage.</p>
      <p>European Commission President Ursula von der Leyen said the package demonstrated the EU''s "unwavering determination to ensure that sanctions are not merely announced but effectively enforced."</p>
      <p>Russia''s Foreign Ministry dismissed the measures as "economic self-harm masquerading as foreign policy" and warned of retaliatory restrictions on European agricultural imports and overflight rights.</p>', 'Dhananjay Singh', 'World', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=1200&h=750&fit=crop', 'European Council headquarters in Brussels, where the fifteenth sanctions package was formally adopted | Photo: European Council / Audiovisual Service', NULL, 0, 0, 'published', 15, '["EU","Russia","Sanctions","Ukraine"]', 'english', '2026-09-06T16:12:18.414Z', '2026-09-06T23:12:18.414Z', '2026-09-06T23:12:18.414Z');
